def seed_masheed(apps, schema_editor):
    """Create the deployment's company once (docs/migration-h1.5.md §3)."""
    Organization = apps.get_model("academy", "Organization")
    alias = schema_editor.connection.alias
    try:
        organization_id = UUID(str(settings.ACADEMY_ORGANIZATION_ID))
    except (TypeError, ValueError) as error:
        raise RuntimeError("ACADEMY_ORGANIZATION_ID must be a UUID") from error

    clash = Organization.objects.using(alias).filter(slug="masheed").exclude(id=organization_id)
    if clash.exists():
        raise RuntimeError(
            "slug 'masheed' already belongs to another organization; refusing to seed a second one"
        )
    Organization.objects.using(alias).get_or_create(
        id=organization_id,
        defaults={
            "name_ar": settings.ACADEMY_COMPANY_NAME,
            "slug": "masheed",
            "status": "active",
            "default_language": settings.LANGUAGE_CODE,
            "timezone": settings.ACADEMY_BUSINESS_TZ,
        },
    )


def unseed_masheed(apps, schema_editor):
    """Reverse the seed, but never destroy a company that already carries tenant data."""
    Organization = apps.get_model("academy", "Organization")
    Membership = apps.get_model("academy", "Membership")
    Department = apps.get_model("academy", "Department")
    alias = schema_editor.connection.alias
    organization_id = UUID(str(settings.ACADEMY_ORGANIZATION_ID))
    if (
        Membership.objects.using(alias).filter(organization_id=organization_id).exists()
        or Department.objects.using(alias).filter(organization_id=organization_id).exists()
    ):
        raise RuntimeError(
            "refusing to reverse the seed: the company has memberships or departments"
        )
    Organization.objects.using(alias).filter(id=organization_id, slug="masheed").delete()


